import json,re,html,collections,xml.etree.ElementTree as ET
s=json.load(open('source.json')); a=json.load(open('answer.json')); r=json.load(open('reference-targets.json'))
def plain(x):return re.sub(r'\\s+',' ',html.unescape(re.sub(r'<["'^>]+>'"','',x or ''))).strip()
allowed=set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
errors=[]
assert len(s)==len(a)==24
for old,new in zip(s,a):
 n=old['number']
 for k in ['code_id','source_id','source_sha256','number']:
  if new[k]"'!=old[k]:errors.append((n,'"'id',k))
 imp=new['substantive_impact']
 for k in ['assessment','scope_limitations','new_burdens_review']:
  if len(imp[k])<40:errors.append((n,'short',k))
 if old['benefit_check_required'] and len(new.get('benefit_review',''))<100:errors.append((n,'benefit'))
 if new['status']=='retained_unchanged':
  assert new['proposed_xml'] is None and imp['effects']==[] and imp['classification']=='retained_necessary'
 else:
  root=ET.fromstring('<root>'+new['proposed_xml']+'</root>')
  for el in root.iter():
   if el is root:continue
   if el.tag not in allowed:errors.append((n,'tag',el.tag))
   for k,v in el.attrib.items():
    if k not in ['rowspan','colspan'] or not v.isdigit():errors.append((n,'attr',k,v))
  if new.get('change_type')=='full_repeal':
   assert plain(new['proposed_xml']).startswith(('Le présent article est abrogé','Abrogé')) and len(new['repeal_scope'])>=30
  if new.get('change_type')=='normative_reduction':
   assert all(len(x)>=30 for x in new['removed_provisions'])
 for e in imp['effects']:
  if len(e['source_quote'])<12 or e['source_quote'] not in plain(old['source_xml']):errors.append((n,'source_quote',e['source_quote']))
  if len(e['proposed_quote'])<12 or e['proposed_quote'] not in plain(new['proposed_xml']):errors.append((n,'proposed_quote',e['proposed_quote']))
  if not re.fullmatch('[a-z0-9][a-z0-9-]{5,95}',e['measure_id']):errors.append((n,'measure_id',e['measure_id']))
 req=r['requirements'][old['code_id']+'|'+old['source_id']]
 if [x['target_key'] for x in new['reference_checks']] "'!= req:errors.append((n,'"'ref coverage'))
 for ch in new['reference_checks']:
  if ch['view_sha256'] "'!= r['"'targets'][ch['target_key']]['view_sha256'] or len(ch['assessment'])<80:errors.append((n,'ref invalid'))
print('ERRORS',json.dumps(errors,ensure_ascii=False))
print('STATUSES',dict(collections.Counter(x['status'] for x in a)))
print('IMPACTS',dict(collections.Counter(x['substantive_impact']['classification'] for x in a)))
print('CHECKS',sum(len(x['reference_checks']) for x in a))
for x in a:print(x['number'],x['status'],x.get('change_type',''),len(x['proposed_xml'] or ''))
PY"

